import{useEffect,useMemo,useState}from'react';import{Button,Card,Dropdown,Input,Modal,Select,Space,Table,Tabs,Tag,Tooltip,Typography,message}from'antd';import{DeleteOutlined,EditOutlined,EyeOutlined,MoreOutlined,SearchOutlined}from'@ant-design/icons';import type{ColumnsType}from'antd/es/table';import{useNavigate}from'react-router-dom';import type{ReactNode}from'react';import{ThirdPartyPlatformSpec}from'./platforms';import{useAuth}from'../../../hooks/useAuth';import{useSmartDraft}from'../../agent-center/smart/store';const{Text,Link}=Typography;
type Status='草稿'|'评测中'|'评测通过'|'退回修改';type Task={id:string;agentCode:string;agentName:string;version:string;status:Status;lastEditTime:string;submitTime:string;completeTime?:string;resultDesc?:string};
const names=['超声检查预约助手','CT影像智能分析平台','处方智能审核助手','住院护理风险预警助手','糖尿病随访管理助手'];const statuses:Status[]=['评测通过','评测中','草稿','退回修改','评测通过'];
const seed=(p:ThirdPartyPlatformSpec):Task[]=>names.map((agentName,i)=>({id:`${p.key}-${i+1}`,agentCode:`AG-${String(i+1).padStart(4,'0')}`,agentName,version:p.versions[i%p.versions.length],status:statuses[i],lastEditTime:`2026-08-${String(10+i).padStart(2,'0')} 09:30:00`,submitTime:`2026-08-${String(10+i).padStart(2,'0')} 10:20:00`,completeTime:i%3===0?`2026-08-${String(11+i).padStart(2,'0')} 15:40:00`:undefined,resultDesc:statuses[i]==='评测通过'?'各项评测维度均达到平台准入要求。':statuses[i]==='退回修改'?'部分评测维度未达到准入要求，请修改后重新提交。':undefined}));
export default function ThirdPartyTaskList({platform,moduleSwitcher}:{platform:ThirdPartyPlatformSpec;moduleSwitcher:ReactNode}){const nav=useNavigate();const[tasks,setTasks]=useState(()=>seed(platform));const[tab,setTab]=useState<'all'|Status>('all');const[q,setQ]=useState('');const[status,setStatus]=useState<Status>();const tabs:[('all'|Status),string][]=[['all','全部任务'],['草稿','草稿'],['评测中','评测中'],['评测通过','评测通过'],['退回修改','退回修改']];useEffect(()=>{const onJump=(event:Event)=>{const nextTab=(event as CustomEvent<string>).detail;if(!tabs.some(([key])=>key===nextTab))return;setTab(nextTab as Status);setStatus(undefined)};window.addEventListener('agent-jump-tab',onJump);return()=>window.removeEventListener('agent-jump-tab',onJump)},[]);const visible=useMemo(()=>tasks.filter(x=>(tab==='all'||x.status===tab)&&(!status||x.status===status)&&(!q||`${x.agentName}${x.agentCode}`.toLowerCase().includes(q.toLowerCase()))),[tasks,tab,q,status]);const remove=(r:Task)=>Modal.confirm({title:'确认删除评测任务？',content:`删除后「${r.agentName}」的草稿无法恢复。`,okText:'删除',okType:'danger',cancelText:'取消',onOk:()=>{setTasks(x=>x.filter(y=>y.id!==r.id));message.success('已删除')}});const cols:ColumnsType<Task>=[{title:'序号',width:64,render:(_,__,i)=>i+1},{title:'智能体编号',dataIndex:'agentCode',width:120},{title:'智能体名称',dataIndex:'agentName',width:180,ellipsis:true,render:v=><Tooltip title={v}><Link>{v}</Link></Tooltip>},{title:'智能体版本',dataIndex:'version',width:100,render:v=><Tag>{v}</Tag>},{title:'评测平台',width:180,render:()=>platform.name},{title:'评测维度',width:260,render:()=>{const v=platform.dimensions.join(' / ');return <Tooltip title={v}><Text ellipsis style={{width:240}}>{v}</Text></Tooltip>}}];if(tab==='all')cols.push({title:'评测状态',dataIndex:'status',width:110,render:v=><Tag color={v==='评测通过'?'success':v==='退回修改'?'error':v==='评测中'?'processing':'default'}>{v}</Tag>});if(tab==='草稿')cols.push({title:'最后编辑时间',dataIndex:'lastEditTime',width:170});if(tab==='评测中')cols.push({title:'提交评测时间',dataIndex:'submitTime',width:170});if(tab==='评测通过'||tab==='退回修改')cols.push({title:'评测结果',dataIndex:'status',width:110,render:v=><Tag color={v==='评测通过'?'success':'error'}>{v}</Tag>},{title:'评测结果说明',dataIndex:'resultDesc',width:240,ellipsis:true},{title:'评测完成时间',dataIndex:'completeTime',width:170});cols.push({title:'操作',fixed:'right',width:150,render:(_,r)=><Space size={4}><Button type="link" size="small" icon={<EyeOutlined/>} onClick={()=>nav(`/app/evaluation/tasks/platform/${platform.key}/${r.id}`)}>查看详情</Button>{r.status==='草稿'&&<Dropdown trigger={['click']} menu={{items:[{key:'edit',label:'编辑',icon:<EditOutlined/>,onClick:()=>nav(`/app/evaluation/tasks/platform/${platform.key}/create?taskId=${r.id}`)},{key:'delete',label:'删除',icon:<DeleteOutlined/>,danger:true,onClick:()=>remove(r)}]}}><Button type="link" size="small" icon={<MoreOutlined/>} style={{padding:0}}>更多</Button></Dropdown>}</Space>});return <><Card style={{marginTop:16}}>{moduleSwitcher}<Tabs activeKey={tab} onChange={x=>{setTab(x as typeof tab);setStatus(undefined)}} items={tabs.map(([key,label])=>({key,label:<Space size={4}><span>{label}</span><Text type="secondary">({key==='all'?tasks.length:tasks.filter(x=>x.status===key).length})</Text></Space>}))}/><Space wrap size={8}><Input allowClear prefix={<SearchOutlined/>} placeholder="搜索智能体名称 / 编号" value={q} onChange={e=>setQ(e.target.value)} style={{width:280}}/>{tab==='all'&&<Select allowClear placeholder="评测状态" value={status} onChange={setStatus} style={{width:160}} options={tabs.slice(1).map(([value,label])=>({value,label}))}/>}<Button onClick={()=>{setQ('');setStatus(undefined)}}>重置</Button><Text type="secondary">共 {visible.length} 条</Text></Space></Card><div style={{background:'#fff',borderRadius:8,marginTop:16,border:'1px solid #F0F0F0'}}><Table rowKey="id" columns={cols} dataSource={visible} pagination={{pageSize:10,showTotal:total=>`共 ${total} 条`}} scroll={{x:1500}}/></div></>}
